package mz.co.aprendaacodar.course.service;
import mz.co.aprendaacodar.course.dto.CourseDtos.*;import mz.co.aprendaacodar.course.entity.Course;import mz.co.aprendaacodar.course.repository.CourseRepository;import mz.co.aprendaacodar.user.entity.User;import mz.co.aprendaacodar.user.repository.UserRepository;import mz.co.aprendaacodar.common.exception.*;import mz.co.aprendaacodar.common.enums.Enums.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
import mz.co.aprendaacodar.audit.service.AuditService;
import mz.co.aprendaacodar.storage.StorageService;
@Service public class CourseService {
 private final CourseRepository courses;private final UserRepository users;private final AuditService audit;private final StorageService storage;public CourseService(CourseRepository c,UserRepository u,AuditService audit,StorageService storage){courses=c;users=u;this.audit=audit;this.storage=storage;}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public List<CourseResponse> published(){return courses.findAllByStatus(CourseStatus.PUBLISHED).stream().map(this::map).toList();}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public CourseResponse publicBySlug(String slug){return map(courses.findBySlugAndStatus(slug,CourseStatus.PUBLISHED).orElseThrow(()->new ResourceNotFoundException("Curso não encontrado.")));}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public List<CourseResponse> mine(UUID teacher){return courses.findAllByTeacherId(teacher).stream().map(this::map).toList();}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public List<CourseResponse> all(){return courses.findAll().stream().map(this::map).toList();}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public CourseResponse get(UUID id){return map(find(id));}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public void assertCanManage(UUID actor,UUID id){Course c=find(id);if(!c.getTeacher().getId().equals(actor)&&user(actor).getRole()!=UserRole.ADMIN)throw new ForbiddenOperationException("Não pode gerir este curso.");}
 @Transactional public CourseResponse create(UUID actor,CourseRequest r,boolean admin){User teacher=users.findById(admin&&actor==null?UUID.randomUUID():actor).orElseThrow(()->new ResourceNotFoundException("Utilizador não encontrado."));if(!admin&&teacher.getRole()!=UserRole.TEACHER)throw new ForbiddenOperationException("Apenas professores podem criar cursos.");Course c=courses.save(new Course(r.title(),r.shortDescription(),r.description(),r.coverImageKey(),r.price(),r.durationHours(),r.prerequisites(),r.learningOutcomes(),r.curriculumMode(),teacher));return map(c);}
 @Transactional public CourseResponse update(UUID actor,UUID id,CourseRequest r,boolean admin){Course c=find(id);if(!admin&&!c.getTeacher().getId().equals(actor))throw new ForbiddenOperationException("Não pode gerir cursos de outro professor.");c.update(r.title(),r.shortDescription(),r.description(),r.coverImageKey(),r.price(),r.durationHours(),r.prerequisites(),r.learningOutcomes(),r.curriculumMode());return map(c);}
 @Transactional public void submit(UUID actor,UUID id){Course c=find(id);if(!c.getTeacher().getId().equals(actor))throw new ForbiddenOperationException("Não pode gerir cursos de outro professor.");if(c.getStatus()==CourseStatus.PUBLISHED||c.getStatus()==CourseStatus.ARCHIVED)throw new BusinessException("Este curso não pode ser submetido neste estado.");c.submit();}
 @Transactional public void approve(UUID actor,UUID id){Course c=find(id);User admin=user(actor);c.approve(admin);audit.record(admin,"COURSE_APPROVED","Course",id,Map.of());}
 @Transactional public void reject(UUID actor,UUID id,String reason){Course c=find(id);User admin=user(actor);c.reject(admin,reason);audit.record(admin,"COURSE_REJECTED","Course",id,Map.of("reason",reason));}
 @Transactional public void archive(UUID actor,UUID id){Course c=find(id);c.archive();audit.record(user(actor),"COURSE_ARCHIVED","Course",id,Map.of());}
 private User user(UUID id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("Utilizador não encontrado."));}private Course find(UUID id){return courses.findById(id).orElseThrow(()->new ResourceNotFoundException("Curso não encontrado."));}
 private CourseResponse map(Course c){return new CourseResponse(c.getId(),c.getTitle(),c.getSlug(),c.getShortDescription(),c.getDescription(),c.getCoverImageKey()==null?null:storage.url(c.getCoverImageKey(),true),c.getPrice(),c.getCurrency(),c.getDurationHours(),new TeacherSummary(c.getTeacher().getId(),c.getTeacher().getFirstName(),c.getTeacher().getLastName(),null),c.getCurriculumMode(),c.getStatus());}
}
